def get_rotations(shape):
    def rotate(s):
        # rotate 90 degrees clockwise
        return sorted([(y, -x) for x, y in s])

    rotations = []
    current = shape
    for _ in range(4):
        # Normalize
        min_x = min(x for x, y in current)
        min_y = min(y for x, y in current)
        normalized = sorted([(x - min_x, y - min_y) for x, y in current])
        if normalized not in rotations:
            rotations.append(normalized)
        current = rotate(current)
    return rotations

